// Apply the specified single-step period-63 boundary correction. For the
// stencil offsets used here, q is always between -4 and 67.
__device__ __forceinline__ int corrected_y(int q)
{
  return q + 63 * ((q < 0) - (q > 63));
}

// Direct-global Y derivative: one output per thread, with no shared memory
// or per-thread reuse. Each warp spans adjacent X values at fixed Y and Z.
__global__ void derivative_y(const float *f, float *df)
{
  int i = blockIdx.x * blockDim.x + threadIdx.x;
  int j = blockIdx.y * blockDim.y + threadIdx.y;
  int k = blockIdx.z;

  int globalIdx = k * mx * my + j * mx + i;
  int rowBase = k * mx * my + i;

  int ym1 = corrected_y(j - 1);
  int yp1 = corrected_y(j + 1);
  int ym2 = corrected_y(j - 2);
  int yp2 = corrected_y(j + 2);
  int ym3 = corrected_y(j - 3);
  int yp3 = corrected_y(j + 3);
  int ym4 = corrected_y(j - 4);
  int yp4 = corrected_y(j + 4);

  df[globalIdx] =
    ( c_ay * ( f[rowBase + yp1 * mx] - f[rowBase + ym1 * mx] )
    + c_by * ( f[rowBase + yp2 * mx] - f[rowBase + ym2 * mx] )
    + c_cy * ( f[rowBase + yp3 * mx] - f[rowBase + ym3 * mx] )
    + c_dy * ( f[rowBase + yp4 * mx] - f[rowBase + ym4 * mx] ) );
}

extern "C" void run(const float *A, const float *B, float *C, float *scratch,
